import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.9QNR97T-.js";const u=JSON.parse('{"title":"设置页与消息端点","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/messages.md","filePath":"plugins/messages.md"}'),d={name:"plugins/messages.md"};function o(i,e,n,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="设置页与消息端点" tabindex="-1">设置页与消息端点 <a class="header-anchor" href="#设置页与消息端点" aria-label="Permalink to &quot;设置页与消息端点&quot;">​</a></h1><h2 id="同步调用-28" tabindex="-1">同步调用（28） <a class="header-anchor" href="#同步调用-28" aria-label="Permalink to &quot;同步调用（28）&quot;">​</a></h2><p>拿到 <a href="/LyraPlayer-docs-site/plugins/service-context">服务上下文</a> 的句柄后，查询宿主 <code>LYRA_INTERFACE_SERVICE_CALL</code>（版本 3，<code>sizeof(LyraServiceCallV3)</code>），用 <code>lyra_service_call</code> 发出带接口 ID 的消息。注册器只访问选中实现。此操作在宿主帧线程同步完成，嵌套消息和字段指针在本进程调用期间有效。回复需要跨调用使用时立即复制。</p><p>消息声明操作、字段类型和容量。未知可选字段可忽略，未知必需字段及重复字段应拒绝。I64、F64 和 HANDLE 使用 8 字节，普通 UTF8 消息按端点约定包含结尾 NUL。通用请求最多 64 个字段、1 MiB。状态值和字段校验见 <a href="/LyraPlayer-docs-site/downloads/sdk/include/plugin/message_contracts.h">message_contracts.h</a>。</p><h2 id="设置页-26" tabindex="-1">设置页（26） <a class="header-anchor" href="#设置页-26" aria-label="Permalink to &quot;设置页（26）&quot;">​</a></h2><p>任意选中服务可提供 <code>LyraSettingsPageV3</code>，宿主枚举接口并创建设置入口。</p><table tabindex="0"><thead><tr><th>操作</th><th>用法</th></tr></thead><tbody><tr><td>INFO</td><td>返回页面标题、入口名、行数、页号与修订号。可带确认提示和通知。</td></tr><tr><td>ROW</td><td>按 INDEX 提供标题、详情、按钮文字、标志及滑块参数。</td></tr><tr><td>OPEN / BACK</td><td>OPEN 回到插件首页。BACK 先取消当前确认，再回上一页，首页可返回 UNSUPPORTED。</td></tr><tr><td>ACTIVATE</td><td>对 INDEX 执行操作，可带 SECONDARY 或 VALUE。</td></tr><tr><td>CONFIRM</td><td>以 ACCEPT 确认或取消。</td></tr><tr><td>HOST_CAPABILITIES</td><td>查询宿主支持的行类型。</td></tr></tbody></table><p><code>INFO.ENTRY_PARENT</code> 省略时在设置首页。可用的现有父页为 <code>settings.scan</code>、<code>settings.lyrics</code>、<code>settings.transitions</code>、<code>settings.haptics</code>、<code>settings.visualization</code>。未知父页不显示入口。插件负责校验、状态变更和持久化，宿主负责列表、滑块和确认交互。</p><h2 id="媒体操作-21、22、27" tabindex="-1">媒体操作（21、22、27） <a class="header-anchor" href="#媒体操作-21、22、27" aria-label="Permalink to &quot;媒体操作（21、22、27）&quot;">​</a></h2><ul><li><strong>21 个人资料库</strong>：ADD 接受本地 TRACK，或由 PROVIDER 与 UID 组成的来源引用。两种写法互斥。LIST 可能返回数字字符串或 provider/uid 对象。根级 provider 仅解释该快照中的数字简写。</li><li><strong>22 听歌记录</strong>：按头文件查询记录与汇总，检查回复字段类型。睡眠计时是同一接口的独立操作。</li><li><strong>27 队列动作</strong>：APPEND 或 NEXT 接受当前媒体上下文的 COLLECTION 和 ROW。接收成功后宿主复制条目数据。重复曲目可有独立队列条目。请求 ID、行号及队列条目 ID 不适合作为跨进程标识。</li></ul><h2 id="其他消息能力" tabindex="-1">其他消息能力 <a class="header-anchor" href="#其他消息能力" aria-label="Permalink to &quot;其他消息能力&quot;">​</a></h2><p><a href="/LyraPlayer-docs-site/plugins/clipboard">剪贴板 19</a>、<a href="/LyraPlayer-docs-site/plugins/links">链接 20</a>、<a href="/LyraPlayer-docs-site/downloads/sdk/include/plugin/transition_contracts.h">音频过渡 23</a>、<a href="/LyraPlayer-docs-site/downloads/sdk/include/plugin/stem_contracts.h">分轨分析 24</a>、<a href="/LyraPlayer-docs-site/downloads/sdk/include/plugin/font_contracts.h">字体 25</a> 各自定义操作和标签。先按实际端点查询，再根据返回结果启用功能。<a href="/LyraPlayer-docs-site/reference/abi">接口总表</a></p>',12)])])}const _=t(d,[["render",o]]);export{u as __pageData,_ as default};
